if (!$json.messages || !$json.messages.length) {
  return [];
}

const msgId = $json.messages[0].id;
const waId = $json.contacts[0].wa_id;
return [{ json: { ...$json, msgId, waId } }];

return [{ json: {
  wa_id: $('WhatsApp Trigger').first().json.contacts[0].wa_id,
  name: $('WhatsApp Trigger').first().json.contacts[0].profile.name,
  phone_number_id: $('WhatsApp Trigger').first().json.metadata.phone_number_id,
  text: $json.text,
  type: 'audio'
} }];

return [{ json: {
  wa_id: $('Extract Message ID').item.json.contacts[0].wa_id,
  name: $('Extract Message ID').item.json.contacts[0].profile.name,
  phone_number_id: $('Extract Message ID').item.json.metadata.phone_number_id,
  text: $('Extract Message ID').item.json.messages[0].text.body,
  type: 'text'
} }];

const pending = JSON.parse($json.pendingData || '{}');
return [{ json: {
  media_id: pending.media_id,
  description: $('Code in JavaScript').item.json.text,
  wa_id: $('Code in JavaScript').item.json.wa_id,
  phone_number_id: $('Code in JavaScript').item.json.phone_number_id,
  name: $('Code in JavaScript').item.json.name
} }];

const text = $json.text || "";
const isArabic = /[\u0600-\u06FF]/.test(text);
return [{
  json: {
    ...$json,
    forcedLang: isArabic ? "ar" : "en"
  }
}];
